def apply(inputs, premises):
    spans = inputs.get('source_spans', [])
    answers = inputs.get('semantic_answers', [])
    seen = set()
    for answer in answers:
        if isinstance(answer, dict) and isinstance(answer.get('id'), str):
            seen.add(answer.get('id'))
    queries = []
    all_ids = []
    i = 0
    while i < len(spans):
        span = spans[i]
        if isinstance(span, dict) and 'id' in span and isinstance(span.get('text'), str):
            all_ids.append(span.get('id'))
        i += 1
    i = 0
    while i < len(spans):
        span = spans[i]
        if not isinstance(span, dict) or 'id' not in span or not isinstance(span.get('text'), str):
            i += 1
            continue
        start = max(0, i - 2)
        window = []
        parts = []
        j = start
        while j <= i:
            prior = spans[j]
            if isinstance(prior, dict) and 'id' in prior and isinstance(prior.get('text'), str):
                window.append(prior.get('id'))
                parts.append(prior.get('text'))
            j += 1
        low = ' '.join(parts).lower()
        current = span.get('text').lower()
        personnel = ('employee' in low or 'director' in low or 'officer' in low or 'contractor' in low or 'consultant' in low or 'agent' in low or 'representative' in low or 'affiliate' in low or 'controlled' in low or 'third party' in low or 'third-party' in low)
        disclosure = personnel and ('disclos' in low or 'restrict access' in low or 'make accessible' in low or 'provide access' in low)
        if disclosure:
            for operation in ('disclosure_modality', 'disclosure_recipient_scope', 'disclosure_conditions'):
                query_id = operation + '|unit|' + str(span.get('id'))
                if query_id not in seen:
                    queries.append({'id': query_id, 'operation': operation, 'unit_ids': list(window)})
        protected = ('confidential information' in low or 'document' in low or 'material' in low or 'copies' in low or 'copy' in low or 'record' in low)
        disposal = protected and ('return' in low or 'destroy' in low or 'delete' in low)
        retention = ('retain' in current or 'retention' in current or 'archiv' in current or 'keep a copy' in current)
        if disposal:
            for operation in ('disposal_action', 'disposal_material_scope', 'disposal_trigger', 'retention_effect'):
                query_id = operation + '|unit|' + str(span.get('id'))
                if query_id not in seen:
                    queries.append({'id': query_id, 'operation': operation, 'unit_ids': list(window)})
        elif retention:
            query_id = 'retention_effect|unit|' + str(span.get('id'))
            if query_id not in seen:
                queries.append({'id': query_id, 'operation': 'retention_effect', 'unit_ids': list(window)})
        i += 1
    if all_ids:
        anchor = ','.join(str(value) for value in all_ids)
        for operation in ('scan_disclosure_permission', 'scan_disposal_obligation', 'scan_retention_effect'):
            query_id = operation + '|all|' + anchor
            if query_id not in seen:
                queries.append({'id': query_id, 'operation': operation, 'unit_ids': list(all_ids)})
    return {'queries': queries}

